type Leaves<T> = T extends string ? T : { [K in keyof T]: Leaves<T[K]> }[keyof T];

/** A namespace in the `frontend` scope. */
export type FrontendI18nKeysNamespace = keyof typeof FrontendI18nKeys;

/** Any key of one namespace, as the string the translator is called with. */
export type FrontendI18nKeysKey<N extends FrontendI18nKeysNamespace> = Leaves<(typeof FrontendI18nKeys)[N]>;
